// Option 2 for how far a claim reaches: reach scoped by attestation.
// Example: Alice's Roam uid has LocalAccess in graphs A, B and C. Mallory is a co-member in graph A only,
// so she holds A's space password and can make claims as A.
// Green = the claim gives access there. Grey dashed = it doesn't. Blue = reached, but no new access.
// Red-tinted box = a forgery scenario.
// Render: dot -Tsvg dg-accounts-claim-reach-option2.dot -o dg-accounts-claim-reach-option2.svg
// Layout: a 2x2 grid. newrank lets rank=same span clusters: the four claims of a row share a rank.
// Invisible edges from each top space to the claim below keep the bottom row under the top row.
// ordering=out keeps spaces in edge order (A, B, C).
digraph option2 {
  newrank=true;
  ordering=out;
  nodesep=0.3;
  ranksep=0.45;
  fontname="Helvetica";
  node [fontname="Helvetica", fontsize=11, shape=box, style="filled", fillcolor="#ffffff", color="#333333", width=1.1];
  edge [arrowsize=0.7];

  // Reached: green. Not reached: grey dashed. Already had it: blue.
  subgraph cluster_2a {
    label=<<b>2a. Alice connects from graph A, no proof</b>>; style=filled; fillcolor="#f7f7f7"; color="#bbbbbb"; margin=14;
    c2a [label="Alice's claim\nasserted, vouched by A"];
    a2a [label="A", fillcolor="#d3f8d5", color="#439946"];
    b2a [label="B", fillcolor="#eeeeee", color="#aaaaaa", fontcolor="#888888", style="filled,dashed"];
    d2a [label="C", fillcolor="#eeeeee", color="#aaaaaa", fontcolor="#888888", style="filled,dashed"];
    c2a -> a2a; c2a -> b2a [style=invis]; c2a -> d2a [style=invis];
  }
  subgraph cluster_2b {
    label=<<b>2b. She later opens the plugin in B too</b>>; style=filled; fillcolor="#f7f7f7"; color="#bbbbbb"; margin=14;
    c2b [label="Alice's claim\nasserted, vouched by A and B"];
    a2b [label="A", fillcolor="#d3f8d5", color="#439946"];
    b2b [label="B", fillcolor="#d3f8d5", color="#439946"];
    d2b [label="C", fillcolor="#eeeeee", color="#aaaaaa", fontcolor="#888888", style="filled,dashed"];
    c2b -> a2b; c2b -> b2b; c2b -> d2b [style=invis];
  }
  subgraph cluster_2c {
    label=<<b>2c. Mallory forges from A: she gains nothing new</b>>; style=filled; fillcolor="#fff0f0"; color="#e51000"; margin=14;
    c2c [label="Mallory's forged claim\nasserted, vouched by A"];
    a2c [label="A\n(she already reads it\nwith the password)", fillcolor="#cee9ff", color="#0254a0"];
    b2c [label="B", fillcolor="#eeeeee", color="#aaaaaa", fontcolor="#888888", style="filled,dashed"];
    d2c [label="C", fillcolor="#eeeeee", color="#aaaaaa", fontcolor="#888888", style="filled,dashed"];
    c2c -> a2c; c2c -> b2c [style=invis]; c2c -> d2c [style=invis];
  }
  subgraph cluster_2d {
    label=<<b>2d. Alice proves her identity: same claim, wider reach</b>>; style=filled; fillcolor="#f7f7f7"; color="#bbbbbb"; margin=14;
    c2d [label="Alice's claim\nattested"];
    a2d [label="A", fillcolor="#d3f8d5", color="#439946"];
    b2d [label="B", fillcolor="#d3f8d5", color="#439946"];
    d2d [label="C", fillcolor="#d3f8d5", color="#439946"];
    c2d -> a2d; c2d -> b2d; c2d -> d2d;
  }

  { rank=same; c2a; c2b; }
  { rank=same; c2c; c2d; }
  b2a -> c2c [style=invis];
  b2b -> c2d [style=invis];
}

// Option 1 for how far a claim reaches: reach follows identity.
// Example: Alice's Roam uid has LocalAccess in graphs A, B and C. Mallory is a co-member in graph A only,
// so she holds A's space password and can make claims as A.
// Green = the claim gives access there. Red = access a forger would gain.
// Red-tinted box = a forgery scenario.
// Render: dot -Tsvg dg-accounts-claim-reach-option1.dot -o dg-accounts-claim-reach-option1.svg
// Layout: newrank lets rank=same span clusters, so both claims share a rank.
// ordering=out keeps spaces in edge order (A, B, C).
digraph option1 {
  newrank=true;
  ordering=out;
  nodesep=0.3;
  ranksep=0.45;
  fontname="Helvetica";
  node [fontname="Helvetica", fontsize=11, shape=box, style="filled", fillcolor="#ffffff", color="#333333", width=1.1];
  edge [arrowsize=0.7];

  subgraph cluster_1a {
    label=<<b>1a. Access starts only once Alice proves her identity (L1, L6 or L8)</b>>; style=filled; fillcolor="#f7f7f7"; color="#bbbbbb"; margin=14;
    c1a [label="Alice's claim\nattested"];
    a1a [label="A", fillcolor="#d3f8d5", color="#439946"];
    b1a [label="B", fillcolor="#d3f8d5", color="#439946"];
    d1a [label="C", fillcolor="#d3f8d5", color="#439946"];
    c1a -> a1a; c1a -> b1a; c1a -> d1a;
  }
  subgraph cluster_1b {
    label=<<b>1b. Why proof must come first: an accepted assertion would reach every space</b>>; style=filled; fillcolor="#fff0f0"; color="#e51000"; margin=14;
    c1b [label="Mallory's forged claim\nmade as space A\n(if assertions were accepted)"];
    a1b [label="A", fillcolor="#fcb8b8", color="#e51000"];
    b1b [label="B", fillcolor="#fcb8b8", color="#e51000"];
    d1b [label="C", fillcolor="#fcb8b8", color="#e51000"];
    c1b -> a1b; c1b -> b1b; c1b -> d1b;
  }

  { rank=same; c1a; c1b; }
}

// Discourse Graphs accounts: which login reaches what, and through which link.
// Read left to right: a login gives a principal; the principal reaches other principals;
// each principal opens some content.
// Dashed = proposed or unmerged (personal accounts, claims, agents, everyone).
// Reach sets: self_to_spaces() = caller + spaces it acts for;
// self_to_groups() adds their groups; self_to_everyone() adds everyone.
// Render: dot -Tsvg dg-accounts-identities.dot -o dg-accounts-identities.svg
// Layout: newrank with rank=same keeps all logins in the first column and all content in the last.
digraph identities {
  newrank=true;
  rankdir=LR;
  nodesep=0.35;
  ranksep=0.6;
  fontname="Helvetica";
  node [fontname="Helvetica", fontsize=11, shape=box, style="filled", fillcolor="#ffffff", color="#333333"];
  edge [fontname="Helvetica", fontsize=9, arrowsize=0.7];

  subgraph cluster_logins {
    label=<<b>Logins</b>>; style=filled; fillcolor="#fdf6e3"; color="#b58900"; margin=12;
    node [fillcolor="#fffbea", color="#b58900", style="filled,rounded"];
    L_agent [label=<Agent credential<br/><i>read-only access</i>>, style="filled,rounded,dashed"];
    L_person [label=<Personal login<br/>Website: password, Google, ORCID…<br/>plugin: OAuth popup<br/><i>reads, cross-space search,<br/>actions as the person</i>>, style="filled,rounded,dashed"];
    L_space [label=<Space password<br/>plugin, automatic;<br/>Website via auth/token<br/><i>sync, groups, sharing</i>>];
    L_none [label=<No login<br/>Website visitor>, style="filled,rounded,dashed"];
  }

  subgraph cluster_principals {
    label=<<b>Principals</b>>; style=filled; fillcolor="#f7f7f7"; color="#bbbbbb"; margin=12;
    A [label="Agent", style="filled,dashed"];
    P [label="Person", style="filled,dashed"];
    PA [label="PlatformAccount in S\nRoam uid / Obsidian vault id"];
    S [label="Space S"];
    G [label="Group G"];
    E [label="everyone\nevery caller counts,\nlogged in or not", style="filled,dashed"];
  }

  subgraph cluster_content {
    label=<<b>Content</b>>; style=filled; fillcolor="#f0fbf0"; color="#439946"; margin=12;
    node [shape=cylinder, fillcolor="#d3f8d5", color="#439946"];
    C_S [label="S's own content\nread, write"];
    C_G [label="Content shared with G\nread"];
    C_E [label="Public content\nread", style="filled,dashed"];
  }

  { rank=same; L_agent; L_person; L_space; L_none; }
  { rank=same; C_S; C_G; C_E; }

  L_agent -> A [style=dashed];
  L_person -> P [style=dashed];
  L_space -> S;
  L_none -> E [style=dashed];

  A -> P [style=dashed, label="agent_grant: one principal,\nits full reach, capped"];
  A -> S [style=dashed, label="or"];
  P -> PA [style=dashed, label="claims"];
  PA -> S [style=dashed, label="acts for S through LocalAccess\nasserted: vouching space only\nattested: every space with LocalAccess\nwhile the lease lasts, with a cap"];
  S -> G [label="member\n(admin of G if S is)"];
  P -> G [style=dashed, label="direct member,\ne.g. group admin"];

  S -> C_S;
  G -> C_G;
  E -> C_E [style=dashed];
}

