// Discourse Graphs accounts: which login reaches what, and through which link.
// Read left to right: a login gives a principal; the principal reaches other principals;
// each principal opens some content.
// Line styles: solid = today; dashed = proposed for accounts v0, or parallel work not merged yet
// (everyone, MCP sessions for spaces); dotted = after accounts v0.
// Agents (MCP) are not principals: an MCP session is a restricted session of a space or a person.
// Render: dot -Tsvg dg-accounts-identities.dot -o dg-accounts-identities.svg
// Layout: newrank with rank=same keeps all logins in the first column and all content in the last.
// everyone is placed in the column next to content (rank=same with G), so the long arrow is the one
// from "No login" rather than the one into public content.
digraph identities {
  newrank=true;
  rankdir=LR;
  nodesep=0.35;
  ranksep=0.6;
  fontname="Helvetica";
  labelloc=b;
  label=<<font point-size="10">solid: today     dashed: accounts v0, or parallel work not merged yet     dotted: after accounts v0</font>>;
  node [fontname="Helvetica", fontsize=11, shape=box, style="filled", fillcolor="#ffffff", color="#333333"];
  edge [fontname="Helvetica", fontsize=9, arrowsize=0.7];

  subgraph cluster_logins {
    label=<<b>Logins</b>>; style=filled; fillcolor="#fdf6e3"; color="#b58900"; margin=12;
    node [fillcolor="#fffbea", color="#b58900", style="filled,rounded"];
    L_space [label=<Space password<br/>plugin, automatic<br/><i>sync, groups, sharing</i>>];
    L_person [label=<Personal login<br/>Website: password or social login<br/>plugin: OAuth popup<br/><i>reads, cross-space search,<br/>actions as the person</i>>, style="filled,rounded,dashed"];
    L_mcp [label=<MCP session<br/>a restricted session of<br/>a space or a person,<br/>not a separate identity>, style="filled,rounded,dashed"];
    L_none [label=<No login<br/>Website visitor>, style="filled,rounded,dashed"];
  }

  subgraph cluster_principals {
    label=<<b>Principals</b>>; style=filled; fillcolor="#f7f7f7"; color="#bbbbbb"; margin=12;
    P [label="Person", style="filled,dashed"];
    PA [label="PlatformAccount in S\nRoam uid / Obsidian vault id"];
    S [label="Space S"];
    G [label="Group G"];
    E [label="everyone\nevery caller counts,\nlogged in or not", style="filled,dashed"];
  }

  subgraph cluster_content {
    label=<<b>Content</b>>; style=filled; fillcolor="#f0fbf0"; color="#439946"; margin=12;
    node [shape=cylinder, fillcolor="#d3f8d5", color="#439946"];
    C_S [label="S's own content\nread, write"];
    C_G [label="Content shared with G\nread"];
    C_E [label="Public content\nread", style="filled,dashed"];
  }

  { rank=same; L_space; L_person; L_mcp; L_none; }
  { rank=same; C_S; C_G; C_E; }
  // everyone sits in the same column as G, so its arrow to public content stays short.
  { rank=same; G; E; }

  L_person -> P [style=dashed];
  L_space -> S;
  L_mcp -> S [style=dashed, label="for a space"];
  L_mcp -> P [style=dotted, label="as a person"];
  L_none -> E [style=dashed];

  P -> PA [style=dashed, label="claims"];
  PA -> S [style=dashed, label="acts for S\nv0, weak claim: only the space\nwhere the claim was made\nlater, strong claim: every space\nof this PlatformAccount"];
  S -> G [label="member\n(admin of G if S is)"];
  P -> G [style=dotted, label="direct member"];

  S -> C_S;
  G -> C_G;
  E -> C_E [style=dashed];
}

